INSERT INTO public.users (id, email, full_name, avatar_url, department, academic_year, campus, bio, trust_score, verified_student, total_rentals_completed, on_time_return_rate, is_admin)
VALUES 
  ('11111111-1111-1111-1111-111111111111', 'aarav.sharma@campus.edu', 'Aarav Sharma', '/images/avatar_aarav_1791025551672.jpg', 'Mechanical Engineering', 'Senior', 'Main North Campus', 'Senior graduating this spring. Lending out my engineering drafting tools, calculators, and lab gear so younger students save money!', 98, true, 14, 100.0, false),
  ('22222222-2222-2222-2222-222222222222', 'maya.patel@campus.edu', 'Maya Patel', '/images/avatar_maya_1791025540576.jpg', 'Computer Science', 'Junior', 'Engineering Quad', 'Junior CS student & robotics club treasurer. Constantly rotating tech gadgets, microcontrollers, and study guides.', 95, true, 9, 96.0, false),
  ('33333333-3333-3333-3333-333333333333', 'liam.chen@campus.edu', 'Liam Chen', '/images/avatar_aarav_1791025551672.jpg', 'Biological Sciences', 'Sophomore', 'Life Sciences Hub', 'Pre-med sophomore. Sharing microscope slides, organic chemistry modeling kits, and dorm furniture.', 92, true, 6, 94.0, false),
  ('44444444-4444-4444-4444-444444444444', 'sofia.rodriguez@campus.edu', 'Sofia Rodriguez', '/images/avatar_maya_1791025540576.jpg', 'Architecture & Design', 'Freshman', 'South Arts Center', 'First year architecture student always in need of scale model cutters, T-squares, and design reference books.', 89, true, 3, 100.0, false),
  ('99999999-9999-9999-9999-999999999999', 'admin@campus.edu', 'Campus Sustainability Office', '/images/avatar_aarav_1791025551672.jpg', 'Student Affairs & Green Initiative', 'Faculty', 'Administration Hall Room 204', 'Official campus moderation and resource stewardship team supporting the circular student economy.', 100, true, 50, 100.0, true)
INSERT INTO public.items (id, owner_id, title, category, description, photos, condition, price_per_day, is_free, deposit_amount, max_rental_days, pickup_location, campus_spot_preset, is_seniors_sale, status, replacement_cost_estimate)
VALUES
  ('a0000001-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', 'Rotring Precision Engineering Drafter & Drawing Kit', 'Engineering Tools', 'Complete mechanical drawing set including a portable mini-drafter, Rotring compass kit, 30cm steel ruler, 45/60 set squares, and drawing tube.', ARRAY['/images/item_drafting_kit_1791025504839.jpg', '/images/item_cutting_mat_1791091795400.jpg'], 'Like New', 500.00, false, 1000.00, 45, 'Central Library Foyer', 'Central Library Foyer', false, 'available', 8500.00),
  ('a0000002-0000-0000-0000-000000000002', '33333333-3333-3333-3333-333333333333', 'Olympus Compound Educational Lab Microscope', 'Lab Equipment', 'Standard dual-eyepiece compound optical microscope with 4x, 10x, 40x, and 100x objectives and clean slides.', ARRAY['/images/item_lab_microscope_1791025516048.jpg', '/images/item_chemistry_kit_1791091721221.jpg'], 'Like New', 1250.00, false, 5000.00, 14, 'Life Sciences Building 2nd Floor', 'Student Activity Center', false, 'available', 28000.00),
  ('a0000003-0000-0000-0000-000000000003', '22222222-2222-2222-2222-222222222222', 'Texas Instruments TI-84 Plus CE Color Graphing Calculator', 'Electronics', 'TI-84 Plus CE with high-resolution backlit color screen and rechargeable battery.', ARRAY['/images/item_graphing_calc_1791025528089.jpg', '/images/item_arduino_kit_1791091709471.jpg'], 'Gently Used', 300.00, false, 1500.00, 30, 'Computer Science Department Lobby', 'Main Canteen', false, 'available', 12500.00),
  ('a0000004-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', 'Senior Pass-It-On: Complete 1st Year Engineering Physics & Math Bundle', 'Books', 'Halliday & Resnick Fundamentals of Physics (11th Ed) + Thomas Calculus (14th Ed). Free for juniors!', ARRAY['/images/item_physics_books_1791091697574.jpg', '/images/item_algorithms_book_1791091808415.jpg'], 'Good', 0.00, true, 0.00, 90, 'North Hostel Gate B', 'North Hostel Gate', true, 'available', 4500.00),
  ('a0000005-0000-0000-0000-000000000005', '22222222-2222-2222-2222-222222222222', 'Arduino Mega 2560 Starter & Sensor Experimenter Kit', 'Engineering Tools', 'Genuine Arduino Mega 2560 with breadboard, sensors, stepper motors, LCD screen module, and jumpers.', ARRAY['/images/item_arduino_kit_1791091709471.jpg', '/images/item_drafting_kit_1791025504839.jpg'], 'Like New', 400.00, false, 1000.00, 21, 'Robotics Lab, Tech Annex 3', 'Engineering Quad', false, 'available', 6500.00),
  ('a0000006-0000-0000-0000-000000000006', '33333333-3333-3333-3333-333333333333', 'Senior Pass-It-On: Organic Chemistry Molecular Model Set', 'Lab Equipment', '240-piece Prentice Hall molecular model kit for organic chemistry. Free pass-it-on for pre-med juniors.', ARRAY['/images/item_chemistry_kit_1791091721221.jpg', '/images/item_lab_microscope_1791025516048.jpg'], 'Gently Used', 0.00, true, 500.00, 60, 'BioChemistry Quad Bench', 'Central Library Foyer', true, 'available', 3200.00),
  ('a0000007-0000-0000-0000-000000000007', '44444444-4444-4444-4444-444444444444', 'Sony WH-1000XM4 Noise-Cancelling Study Headphones', 'Electronics', 'Active noise cancellation for finals study. Comes with flight adapter and case.', ARRAY['/images/item_sony_headphones_1791091732510.jpg', '/images/item_pocket_projector_1791091782233.jpg'], 'Like New', 750.00, false, 3000.00, 7, 'Arts Library checkout desk', 'Central Library Foyer', false, 'rented', 22990.00),
  ('a0000008-0000-0000-0000-000000000008', '11111111-1111-1111-1111-111111111111', 'Ergonomic High-Back Mesh Study Desk Chair', 'Furniture', 'Breathable lumbar-support ergonomic chair with adjustable armrests.', ARRAY['/images/item_study_chair_1791091747070.jpg'], 'Good', 250.00, false, 2000.00, 60, 'Hostel 4 Ground Floor Common Room', 'North Hostel Gate', false, 'available', 12000.00),
  ('a0000009-0000-0000-0000-000000000009', '11111111-1111-1111-1111-111111111111', 'Academic Graduation Ceremony Gown, Cap & Stole (Size L)', 'Clothing', 'Official commencement gown in matte black finish, size L (fits 5’9” to 6’2”).', ARRAY['/images/item_graduation_gown_1791091757929.jpg', '/images/item_garment_steamer_1791091820780.jpg'], 'Like New', 600.00, false, 1500.00, 5, 'Student Union information booth', 'Student Activity Center', false, 'available', 5000.00),
  ('a0000010-0000-0000-0000-000000000010', '22222222-2222-2222-2222-222222222222', 'Wilson Pro Staff Tennis Racket with Carrying Case & 3 Balls', 'Sports', 'Grip size 3, re-strung at 54 lbs. Great for campus recreation courts.', ARRAY['/images/item_tennis_racket_1791091770029.jpg', '/images/item_commuter_bicycle_1791091834597.jpg'], 'Good', 350.00, false, 1000.00, 7, 'Campus Sports Complex reception', 'Student Activity Center', false, 'available', 11500.00),
  ('a0000011-0000-0000-0000-000000000011', '33333333-3333-3333-3333-333333333333', 'Anker Nebula Capsule Mini Smart Pocket Projector', 'Electronics', '100 ANSI lumen soda-can sized portable projector with 360 sound for club movie nights.', ARRAY['/images/item_pocket_projector_1791091782233.jpg', '/images/item_sony_headphones_1791091732510.jpg'], 'Like New', 900.00, false, 3500.00, 5, 'Bio Quad or Main Canteen', 'Main Canteen', false, 'available', 25000.00),
  ('a0000012-0000-0000-0000-000000000012', '44444444-4444-4444-4444-444444444444', 'Olfa Rotary Cutter & A2 Self-Healing Cutting Mat', 'Engineering Tools', 'High-precision 45mm rotary fabric & cardstock cutter, extra carbide blades, and 24x18 grid mat.', ARRAY['/images/item_cutting_mat_1791091795400.jpg', '/images/item_drafting_kit_1791025504839.jpg'], 'Good', 200.00, false, 500.00, 14, 'Architecture Studio 302', 'Central Library Foyer', false, 'available', 4200.00),
  ('a0000013-0000-0000-0000-000000000013', '22222222-2222-2222-2222-222222222222', 'Introduction to Algorithms (CLRS 4th Edition, Hardcover)', 'Books', 'The classic algorithms textbook in crisp condition with clean margins.', ARRAY['/images/item_algorithms_book_1791091808415.jpg', '/images/item_physics_books_1791091697574.jpg'], 'Like New', 150.00, false, 1000.00, 60, 'CS Dept Turing Hall entrance', 'Engineering Quad', false, 'available', 7800.00),
  ('a0000014-0000-0000-0000-000000000014', '11111111-1111-1111-1111-111111111111', 'Senior Pass-It-On: Dorm Room Clothes Steamer & Handheld Iron', 'Clothing', '1400W handheld garment steamer for placement interviews and formal events.', ARRAY['/images/item_garment_steamer_1791091820780.jpg', '/images/item_graduation_gown_1791091757929.jpg'], 'Good', 0.00, true, 0.00, 4, 'North Hostel reception desk', 'North Hostel Gate', true, 'available', 3500.00),
  ('a0000015-0000-0000-0000-000000000015', '33333333-3333-3333-3333-333333333333', 'Foldable City Commuter Bicycle with Heavy U-Lock & Helmet', 'Sports', '7-speed Dahon folding bike, rolls into classrooms. High security U-lock included.', ARRAY['/images/item_commuter_bicycle_1791091834597.jpg', '/images/item_tennis_racket_1791091770029.jpg'], 'Good', 500.00, false, 2500.00, 14, 'Student Activity Center Bike Racks', 'Student Activity Center', false, 'available', 24000.00),
  ('a0000016-0000-0000-0000-000000000016', '44444444-4444-4444-4444-444444444444', 'Alesis V-Mini 25-Key USB MIDI Controller Keyboard', 'Other', '25 velocity mini keys with 4 drum pads, USB bus powered for laptop music production.', ARRAY['/images/item_midi_keyboard_1791091846444.jpg', '/images/item_sony_headphones_1791091732510.jpg'], 'Like New', 350.00, false, 1000.00, 20, 'Music & Fine Arts wing, Room 112', 'Central Library Foyer', false, 'available', 7500.00),
  ('a0000017-0000-0000-0000-000000000017', '44444444-4444-4444-4444-444444444444', 'Canon EOS M50 Mirrorless Camera Kit with 15-45mm Lens & Bag', 'Electronics', '24.1MP APS-C mirrorless camera with 4K video, 15-45mm image-stabilized lens, 64GB SDXC card, spare battery, and padded shoulder bag.', ARRAY['/images/item_canon_camera_1791091859500.jpg', '/images/item_pocket_projector_1791091782233.jpg'], 'Like New', 800.00, false, 4000.00, 10, 'South Arts Center Media Checkout', 'Central Library Foyer', false, 'available', 48000.00)
